pieces=[]
for r in range(6):
 for c in range(6):
  sq={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if sq<=cells: pieces.append(('sq',sq))
  for missing in [(0,0),(0,1),(1,0),(1,1)]:
   sh={(r+i,c+j) for i in range(2) for j in range(2) if (i,j)!=missing}
   if sh<=cells: pieces.append((f'L{missing}',sh))
sol=[]
def rec(rem,cur):
 if not rem:
  sol.append(cur[:]); return
 x=min(rem)
 for typ,p in pieces:
  if x in p and p<=rem:
   rec(rem-p,cur+[(typ,p)])
rec(cells,[])
len(sol)
